import{_ as r,a0 as o,w as m,s,ao as d,I as a,x as t,a1 as p,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse(`{"title":"在 Linux 下使用 RAID（三）：用两块磁盘创建 RAID 1（镜像） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（三）：用两块磁盘创建 RAID 1（镜像） | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（三）：用两块磁盘创建 RAID 1（镜像） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（三）：用两块磁盘创建 RAID 1（镜像） | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 3 - Setting up RAID 1 (Mirroring) using 'Two Disks' in Linux","title":"在 Linux 下使用 RAID（三）：用两块磁盘创建 RAID 1（镜像）","tag":"RAID","desc":""},"relativePath":"RAID/Part 3 - Setting up RAID 1 (Mirroring) using 'Two Disks' in Linux.md","filePath":"[post].md"}`),c={name:"RAID/Part 3 - Setting up RAID 1 (Mirroring) using 'Two Disks' in Linux.md"};function l(D,e,R,A,u,I){const i=o("Link");return m(),s("div",null,[e[15]||(e[15]=d('<h1 id="在-linux-下使用-raid-三-用两块磁盘创建-raid-1-镜像" tabindex="-1">在 Linux 下使用 RAID（三）：用两块磁盘创建 RAID 1（镜像） <a class="header-anchor" href="#在-linux-下使用-raid-三-用两块磁盘创建-raid-1-镜像" aria-label="Permalink to “在 Linux 下使用 RAID（三）：用两块磁盘创建 RAID 1（镜像）”">​</a></h1><p><strong>RAID 镜像</strong>意味着相同数据的完整克隆（或镜像），分别写入到两个磁盘中。创建 RAID 1 至少需要两个磁盘，而且仅用于读取性能或者可靠性要比数据存储容量更重要的场合。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID1-in-Linux.jpeg" alt="Create Raid1 in Linux"></p><p><em>在 Linux 中设置 RAID 1</em></p><p>创建镜像是为了防止因硬盘故障导致数据丢失。镜像中的每个磁盘包含数据的完整副本。当一个磁盘发生故障时，相同的数据可以从其它正常磁盘中读取。而后，可以从正在运行的计算机中直接更换发生故障的磁盘，无需任何中断。</p><h3 id="raid-1-的特点" tabindex="-1">RAID 1 的特点 <a class="header-anchor" href="#raid-1-的特点" aria-label="Permalink to “RAID 1 的特点”">​</a></h3><ul><li><p>镜像具有良好的性能。</p></li><li><p>磁盘利用率为50％。也就是说，如果我们有两个磁盘每个500GB，总共是1TB，但在镜像中它只会显示500GB。</p></li><li><p>在镜像如果一个磁盘发生故障不会有数据丢失，因为两个磁盘中的内容相同。</p></li><li><p>读取性能会比写入性能更好。</p></li></ul><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>创建 RAID 1 至少要有两个磁盘，你也可以添加更多的磁盘，磁盘数需为2，4，6，8等偶数。要添加更多的磁盘，你的系统必须有 RAID 物理适配器（硬件卡）。</p><p>这里，我们使用软件 RAID 不是硬件 RAID，如果你的系统有一个内置的物理硬件 RAID 卡，你可以从它的功能界面或使用 Ctrl + I 键来访问它。</p>',10)),a("p",null,[e[1]||(e[1]=t("需要阅读: ",-1)),p(i,{href:"https://linux.cn/article-6085-1.html"},{default:n(()=>[...e[0]||(e[0]=[t("介绍 RAID 的级别和概念",-1)])]),_:1})]),e[16]||(e[16]=d(`<h4 id="在我的服务器安装" tabindex="-1">在我的服务器安装 <a class="header-anchor" href="#在我的服务器安装" aria-label="Permalink to “在我的服务器安装”">​</a></h4><pre><code>操作系统 :	CentOS 6.5 Final
IP 地址	 :	192.168.0.226
主机名	 :	rd1.tecmintlocal.com
磁盘 1 [20GB]	 :	/dev/sdb
磁盘 2 [20GB]	 :	/dev/sdc
</code></pre><p>本文将指导你在 Linux 平台上使用 mdadm （用于创建和管理 RAID ）一步步的建立一个软件 RAID 1 （镜像）。同样的做法也适用于如 RedHat，CentOS，Fedora 等 Linux 发行版。</p><h3 id="第1步-安装所需软件并且检查磁盘" tabindex="-1">第1步：安装所需软件并且检查磁盘 <a class="header-anchor" href="#第1步-安装所需软件并且检查磁盘" aria-label="Permalink to “第1步：安装所需软件并且检查磁盘”">​</a></h3><p>1、 正如我前面所说，在 Linux 中我们需要使用 mdadm 软件来创建和管理 RAID。所以，让我们用 yum 或 apt-get 的软件包管理工具在 Linux 上安装 mdadm 软件包。</p><pre><code># yum install mdadm		[在 RedHat 系统]
# apt-get install mdadm 	[在 Debain 系统]
</code></pre><p>2、 一旦安装好<code>mdadm</code>包，我们需要使用下面的命令来检查磁盘是否已经配置好。</p><pre><code># mdadm -E /dev/sd[b-c]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-on-Disks.png" alt="Check RAID on Disks"></p><p><em>检查 RAID 的磁盘</em></p><p>正如你从上面图片看到的，没有检测到任何超级块，这意味着还没有创建RAID。</p><h3 id="第2步-为-raid-创建分区" tabindex="-1">第2步：为 RAID 创建分区 <a class="header-anchor" href="#第2步-为-raid-创建分区" aria-label="Permalink to “第2步：为 RAID 创建分区”">​</a></h3><p>3、 正如我提到的，我们使用最少的两个分区 /dev/sdb 和 /dev/sdc 来创建 RAID 1。我们首先使用<code>fdisk</code>命令来创建这两个分区并更改其类型为 raid。</p><pre><code># fdisk /dev/sdb
</code></pre><p>按照下面的说明</p><ul><li>按 <code>n</code> 创建新的分区。</li><li>然后按 <code>P</code> 选择主分区。</li><li>接下来选择分区号为1。</li><li>按两次回车键默认将整个容量分配给它。</li><li>然后，按 <code>P</code> 来打印创建好的分区。</li><li>按 <code>L</code>，列出所有可用的类型。</li><li>按 <code>t</code> 修改分区类型。</li><li>键入 <code>fd</code> 设置为 Linux 的 RAID 类型，然后按 Enter 确认。</li><li>然后再次使用<code>p</code>查看我们所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Disk-Partitions.png" alt="Create Disk Partitions"></p><p><em>创建磁盘分区</em></p><p>在创建“/dev/sdb”分区后，接下来按照同样的方法创建分区 /dev/sdc 。</p><pre><code># fdisk /dev/sdc
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Second-Partitions.png" alt="Create Second Partitions"></p><p><em>创建第二个分区</em></p><p>4、 一旦这两个分区创建成功后，使用相同的命令来检查 sdb 和 sdc 分区并确认 RAID 分区的类型如上图所示。</p><pre><code># mdadm -E /dev/sd[b-c]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-Partitions-Changes.png" alt="Verify Partitions Changes"></p><p><em>验证分区变化</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Type.png" alt="Check RAID Type"></p><p><em>检查 RAID 类型</em></p><p><strong>注意</strong>: 正如你在上图所看到的，在 sdb1 和 sdc1 中没有任何对 RAID 的定义，这就是我们没有检测到超级块的原因。</p><h3 id="第3步-创建-raid-1-设备" tabindex="-1">第3步：创建 RAID 1 设备 <a class="header-anchor" href="#第3步-创建-raid-1-设备" aria-label="Permalink to “第3步：创建 RAID 1 设备”">​</a></h3><p>5、 接下来使用以下命令来创建一个名为 /dev/md0 的“RAID 1”设备并验证它</p><pre><code># mdadm --create /dev/md0 --level=mirror --raid-devices=2 /dev/sd[b-c]1
# cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID-Device.png" alt="Create RAID Device"></p><p><em>创建RAID设备</em></p><p>6、 接下来使用如下命令来检查 RAID 设备类型和 RAID 阵列</p><pre><code># mdadm -E /dev/sd[b-c]1
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Device-type.png" alt="Check RAID Device type"></p><p><em>检查 RAID 设备类型</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Device-Array.png" alt="Check RAID Device Array"></p><p><em>检查 RAID 设备阵列</em></p><p>从上图中，人们很容易理解，RAID 1 已经创建好了，使用了 /dev/sdb1 和 /dev/sdc1 分区，你也可以看到状态为 resyncing（重新同步中）。</p><h3 id="第4步-在-raid-设备上创建文件系统" tabindex="-1">第4步：在 RAID 设备上创建文件系统 <a class="header-anchor" href="#第4步-在-raid-设备上创建文件系统" aria-label="Permalink to “第4步：在 RAID 设备上创建文件系统”">​</a></h3><p>7、 给 md0 上创建 ext4 文件系统</p><pre><code># mkfs.ext4 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID-Device-Filesystem.png" alt="Create RAID Device Filesystem"></p><p><em>创建 RAID 设备文件系统</em></p><p>8、 接下来，挂载新创建的文件系统到“/mnt/raid1”，并创建一些文件，验证在挂载点的数据</p><pre><code># mkdir /mnt/raid1
# mount /dev/md0 /mnt/raid1/
# touch /mnt/raid1/tecmint.txt
# echo &quot;tecmint raid setups&quot; &gt; /mnt/raid1/tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-RAID-Device.png" alt="Mount Raid Device"></p><p><em>挂载 RAID 设备</em></p><p>9、为了在系统重新启动自动挂载 RAID 1，需要在 fstab 文件中添加条目。打开<code>/etc/fstab</code>文件并添加以下行：</p><pre><code>/dev/md0                /mnt/raid1              ext4    defaults        0 0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/RAID-Automount-Filesystem.png" alt="Raid Automount Device"></p><p><em>自动挂载 Raid 设备</em></p><p>10、 运行<code>mount -av</code>，检查 fstab 中的条目是否有错误</p><pre><code># mount -av
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Errors-in-fstab.png" alt="Check Errors in fstab"></p><p><em>检查 fstab 中的错误</em></p><p>11、 接下来，使用下面的命令保存 RAID 的配置到文件“mdadm.conf”中。</p><pre><code># mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Save-Raid-Configuration.png" alt="Save Raid Configuration"></p><p><em>保存 Raid 的配置</em></p><p>上述配置文件在系统重启时会读取并加载 RAID 设备。</p><h3 id="第5步-在磁盘故障后检查数据" tabindex="-1">第5步：在磁盘故障后检查数据 <a class="header-anchor" href="#第5步-在磁盘故障后检查数据" aria-label="Permalink to “第5步：在磁盘故障后检查数据”">​</a></h3><p>12、我们的主要目的是，即使在任何磁盘故障或死机时必须保证数据是可用的。让我们来看看，当任何一个磁盘不可用时会发生什么。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Raid-Device-Verify.png" alt="Raid Device Verify"></p><p><em>验证 RAID 设备</em></p><p>在上面的图片中，我们可以看到在 RAID 中有2个设备是可用的，并且 Active Devices 是2。现在让我们看看，当一个磁盘拔出（移除 sdc 磁盘）或损坏后会发生什么。</p><pre><code># ls -l /dev | grep sd
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Test-RAID-Devices.png" alt="Test RAID Devices"></p><p><em>测试 RAID 设备</em></p><p>现在，在上面的图片中你可以看到，一个磁盘不见了。我从虚拟机上删除了一个磁盘。此时让我们来检查我们宝贵的数据。</p><pre><code># cd /mnt/raid1/
# cat tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Data.png" alt="Verify RAID Data"></p><p><em>验证 RAID 数据</em></p><p>你可以看到我们的数据仍然可用。由此，我们可以了解 RAID 1（镜像）的优势。在接下来的文章中，我们将看到如何设置一个 RAID 5 条带化分布式奇偶校验。希望这可以帮助你了解 RAID 1（镜像）是如何工作的。</p><hr>`,78)),a("p",null,[e[3]||(e[3]=t("via: ",-1)),p(i,{href:"http://www.tecmint.com/create-raid1-in-linux/"},{default:n(()=>[...e[2]||(e[2]=[t("http://www.tecmint.com/create-raid1-in-linux/",-1)])]),_:1})]),a("p",null,[e[7]||(e[7]=t("作者：",-1)),p(i,{href:"http://www.tecmint.com/author/babinlonston/"},{default:n(()=>[...e[4]||(e[4]=[t("Babin Lonston",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),p(i,{href:"https://github.com/strugglingyouth"},{default:n(()=>[...e[5]||(e[5]=[t("strugglingyouth",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创翻译，",-1)),p(i,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const f=r(c,[["render",l]]);export{h as __pageData,f as default};
